"""Generated by EvalLoop.

Evaluates every criterion in `evalloop/criteria/bigquery_agent_safety.yaml` against
recorded execution traces discovered in `.adk/eval_history/` or the repository.
"""

from __future__ import annotations

import pathlib
import pytest

from evalloop.adapters import adk_evalset
from evalloop.loader import load_pack
from evalloop.primitives import evaluate

CRITERIA_FILE = pathlib.Path(__file__).parent / "criteria" / "bigquery_agent_safety.yaml"
REPO_ROOT = pathlib.Path(__file__).parent.parent


def _load_cases() -> list[adk_evalset.EvalCase]:
    files = adk_evalset.find_evalset_results(REPO_ROOT)
    cases: list[adk_evalset.EvalCase] = []
    for f in files:
        cases.extend(adk_evalset.parse_evalset_result(f))
    return cases


def _get_criteria() -> list[ir.Criterion]:
    pack = load_pack(CRITERIA_FILE)
    return [c for c in pack.criteria if c.check is not None]


@pytest.mark.parametrize("criterion", _get_criteria(), ids=lambda c: c.id)
def test_criterion_against_recorded_traces(criterion: ir.Criterion) -> None:
    cases = _load_cases()
    if not cases:
        pytest.skip("No recorded eval traces found in repository.")

    failures: list[str] = []
    for case in cases:
        res = evaluate(criterion, case.trace)
        if not res.passed:
            failures.append(f"Case {case.eval_id}: {res.explanation}")

    assert not failures, (
        f"Criterion {criterion.id} failed on {len(failures)}/{len(cases)} cases:\n"
        + "\n".join(failures)
    )
